use std::time::Duration;

use clap::{Arg, ArgAction, Command, ValueHint, value_parser};
use clap_complete::Shell;

use crate::duration::parse_duration;
use crate::modules::ALL_MODULES;

pub const SHELLS: [&str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

#[derive(Debug, Clone)]
pub struct AppConfig {
    pub list_modules: bool,
    pub modules: Vec<String>,
    pub speed_factor: f32,
    pub instant_print_lines: u32,
    pub inhibit: bool,
    pub exit_after_time: Option<Duration>,
    pub exit_after_modules: Option<u32>,
    pub print_completions: Option<Shell>,
    pub print_manpage: bool,
}

fn parse_speed_factor(s: &str) -> Result<f32, String> {
    let v: f32 = s.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
    if v < 0.01 {
        return Err("Speed factor must be larger than 0.01".to_string());
    }
    Ok(v)
}

fn parse_exit_after_modules(s: &str) -> Result<u32, String> {
    let v: u32 = s.parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
    if v == 0 {
        return Err("Must be larger than 0".to_string());
    }
    Ok(v)
}

fn parse_exit_after_time(s: &str) -> Result<Duration, String> {
    parse_duration(s).map_err(|e| e.to_string())
}

pub fn build_command() -> Command {
    Command::new("genact")
        .version("1.5.1")
        .author("Sven-Hendrik Haase <svenstaro@gmail.com>")
        .about("A nonsense activity generator")
        .arg(
            Arg::new("list-modules")
                .short('l')
                .long("list-modules")
                .help("List available modules")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("modules")
                .short('m')
                .long("modules")
                .help("Run only these modules")
                .action(ArgAction::Append)
                .value_name("MODULES")
                .value_parser(clap::builder::PossibleValuesParser::new(ALL_MODULES)),
        )
        .arg(
            Arg::new("speed-factor")
                .short('s')
                .long("speed-factor")
                .help("Global speed factor")
                .value_name("SPEED_FACTOR")
                .default_value("1")
                .value_parser(parse_speed_factor),
        )
        .arg(
            Arg::new("instant-print-lines")
                .short('i')
                .long("instant-print-lines")
                .help("Instantly print this many lines")
                .value_name("INSTANT_PRINT_LINES")
                .default_value("0")
                .value_parser(value_parser!(u32)),
        )
        .arg(
            Arg::new("inhibit")
                .long("inhibit")
                .help("Keep the computer awake and the display on while genact is running")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("exit-after-time")
                .long("exit-after-time")
                .help("Exit after running for this long (format example: 2h10min)")
                .value_name("EXIT_AFTER_TIME")
                .value_parser(parse_exit_after_time),
        )
        .arg(
            Arg::new("exit-after-modules")
                .long("exit-after-modules")
                .help("Exit after running this many modules")
                .value_name("EXIT_AFTER_MODULES")
                .value_parser(parse_exit_after_modules),
        )
        .arg(
            Arg::new("print-completions")
                .long("print-completions")
                .help("Generate completion file for a shell")
                .value_name("shell")
                .value_parser(value_parser!(Shell))
                .value_hint(ValueHint::Other),
        )
        .arg(
            Arg::new("print-manpage")
                .long("print-manpage")
                .help("Generate man page")
                .action(ArgAction::SetTrue),
        )
}

pub fn parse_args() -> AppConfig {
    let matches = build_command().get_matches();
    AppConfig {
        list_modules: matches.get_flag("list-modules"),
        modules: matches
            .get_many::<String>("modules")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        speed_factor: *matches.get_one::<f32>("speed-factor").expect("default"),
        instant_print_lines: *matches.get_one::<u32>("instant-print-lines").expect("default"),
        inhibit: matches.get_flag("inhibit"),
        exit_after_time: matches.get_one::<Duration>("exit-after-time").copied(),
        exit_after_modules: matches.get_one::<u32>("exit-after-modules").copied(),
        print_completions: matches.get_one::<Shell>("print-completions").copied(),
        print_manpage: matches.get_flag("print-manpage"),
    }
}
EOF
echo done"}

