//! A small human-friendly duration parser ("2h10min", "1.5s", "3 days").
//!
//! Behaviour was derived purely from observing the reference binary.

use std::fmt;
use std::str::Chars;
use std::time::Duration;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DurationError {
    InvalidCharacter(usize),
    NumberExpected(usize),
    UnknownUnit { unit: String, value: u64 },
    NumberOverflow,
    Empty,
}

impl fmt::Display for DurationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DurationError::InvalidCharacter(off) => write!(f, "invalid character at {}", off),
            DurationError::NumberExpected(off) => write!(f, "expected number at {}", off),
            DurationError::UnknownUnit { unit, value } => {
                if unit.is_empty() {
                    write!(
                        f,
                        "time unit needed, for example {0}sec or {0}ms",
                        value
                    )
                } else {
                    write!(
                        f,
                        "unknown time unit {:?}, supported units: \
                         ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)",
                        unit
                    )
                }
            }
            DurationError::NumberOverflow => write!(
                f,
                "number is too large or cannot be represented without a lack of precision \
                 (values below 1ns are not supported)"
            ),
            DurationError::Empty => write!(f, "value was empty"),
        }
    }
}

impl std::error::Error for DurationError {}

struct Parser<'a> {
    iter: Chars<'a>,
    src: &'a str,
    secs: u64,
    nanos: u64,
}

const NS: u64 = 1_000_000_000;

fn is_unit_char(c: char) -> bool {
    c.is_ascii_alphabetic() || c == 'µ'
}

impl<'a> Parser<'a> {
    fn off(&self) -> usize {
        self.src.len() - self.iter.as_str().len()
    }

    /// Skips whitespace and returns the first digit of the next number.
    fn first_digit(&mut self) -> Result<Option<u64>, DurationError> {
        let off = self.off();
        for c in self.iter.by_ref() {
            match c {
                '0'..='9' => return Ok(Some(c as u64 - '0' as u64)),
                c if c.is_whitespace() => continue,
                _ => return Err(DurationError::NumberExpected(off)),
            }
        }
        Ok(None)
    }

    fn add(&mut self, int: u64, frac: Option<(u64, u64)>, start: usize, end: usize) -> Result<(), DurationError> {
        let unit = &self.src[start..end];
        // (seconds multiplier, nanoseconds multiplier)
        let (sec_mult, ns_mult): (u64, u64) = match unit {
            "nanos" | "nsec" | "ns" => (0, 1),
            "usec" | "us" | "µs" => (0, 1_000),
            "millis" | "msec" | "ms" => (0, 1_000_000),
            "seconds" | "second" | "secs" | "sec" | "s" => (1, 0),
            "minutes" | "minute" | "min" | "mins" | "m" => (60, 0),
            "hours" | "hour" | "hr" | "hrs" | "h" => (3600, 0),
            "days" | "day" | "d" => (86400, 0),
            "weeks" | "week" | "w" => (86400 * 7, 0),
            "months" | "month" | "M" => (2_630_016, 0),
            "years" | "year" | "y" => (31_557_600, 0),
            _ => {
                return Err(DurationError::UnknownUnit {
                    unit: unit.to_string(),
                    value: int,
                })
            }
        };
        let mut sec = int.checked_mul(sec_mult).ok_or(DurationError::NumberOverflow)?;
        let mut nsec = int.checked_mul(ns_mult).ok_or(DurationError::NumberOverflow)?;
        if let Some((frac, scale)) = frac {
            // Fractions of seconds and minutes are resolved in nanoseconds,
            // larger units only support whole seconds.
            if sec_mult == 0 {
                let v = frac.checked_mul(ns_mult).ok_or(DurationError::NumberOverflow)?;
                if v % scale != 0 {
                    return Err(DurationError::NumberOverflow);
                }
                nsec = nsec.checked_add(v / scale).ok_or(DurationError::NumberOverflow)?;
            } else if sec_mult <= 60 {
                let v = frac
                    .checked_mul(sec_mult.checked_mul(NS).ok_or(DurationError::NumberOverflow)?)
                    .ok_or(DurationError::NumberOverflow)?;
                if v % scale != 0 {
                    return Err(DurationError::NumberOverflow);
                }
                nsec = nsec.checked_add(v / scale).ok_or(DurationError::NumberOverflow)?;
            } else {
                let v = frac.checked_mul(sec_mult).ok_or(DurationError::NumberOverflow)?;
                if v % scale != 0 {
                    return Err(DurationError::NumberOverflow);
                }
                sec = sec.checked_add(v / scale).ok_or(DurationError::NumberOverflow)?;
            }
        }
        let mut nsec = self.nanos.checked_add(nsec).ok_or(DurationError::NumberOverflow)?;
        if nsec > NS {
            sec = sec.checked_add(nsec / NS).ok_or(DurationError::NumberOverflow)?;
            nsec %= NS;
        }
        sec = self.secs.checked_add(sec).ok_or(DurationError::NumberOverflow)?;
        self.secs = sec;
        self.nanos = nsec;
        Ok(())
    }

    fn parse(mut self) -> Result<Duration, DurationError> {
        let mut n = self.first_digit()?.ok_or(DurationError::Empty)?;
        'outer: loop {
            let mut frac: Option<(u64, u64)> = None;
            let mut off = self.off();
            // integer part (and optional fraction)
            while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        n = n
                            .checked_mul(10)
                            .and_then(|x| x.checked_add(c as u64 - '0' as u64))
                            .ok_or(DurationError::NumberOverflow)?;
                    }
                    '.' if frac.is_none() => {
                        let mut value: u64 = 0;
                        let mut scale: u64 = 1;
                        let mut digits = 0usize;
                        let mut ended = false;
                        while let Some(c) = self.iter.next() {
                            match c {
                                '0'..='9' => {
                                    value = value
                                        .checked_mul(10)
                                        .and_then(|x| x.checked_add(c as u64 - '0' as u64))
                                        .ok_or(DurationError::NumberOverflow)?;
                                    scale = scale.checked_mul(10).ok_or(DurationError::NumberOverflow)?;
                                    digits += 1;
                                }
                                c if c.is_whitespace() => {}
                                c if is_unit_char(c) => {
                                    if digits == 0 {
                                        return Err(DurationError::InvalidCharacter(off));
                                    }
                                    ended = true;
                                    break;
                                }
                                _ => return Err(DurationError::InvalidCharacter(off)),
                            }
                            off = self.off();
                        }
                        if !ended && digits == 0 {
                            return Err(DurationError::InvalidCharacter(off));
                        }
                        frac = Some((value, scale));
                        if ended {
                            break;
                        }
                        // reached end of input without a unit
                        continue;
                    }
                    c if c.is_whitespace() => {}
                    c if is_unit_char(c) => break,
                    _ => return Err(DurationError::InvalidCharacter(off)),
                }
                off = self.off();
            }
            let start = off;
            let mut off = self.off();
            // unit part
            while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        self.add(n, frac, start, off)?;
                        n = c as u64 - '0' as u64;
                        continue 'outer;
                    }
                    c if c.is_whitespace() => break,
                    c if is_unit_char(c) => {}
                    _ => return Err(DurationError::InvalidCharacter(off)),
                }
                off = self.off();
            }
            self.add(n, frac, start, off)?;
            n = match self.first_digit()? {
                Some(n) => n,
                None => return Ok(Duration::new(self.secs, self.nanos as u32)),
            };
        }
    }
}

pub fn parse_duration(s: &str) -> Result<Duration, DurationError> {
    if s == "0" {
        return Ok(Duration::new(0, 0));
    }
    Parser {
        iter: s.chars(),
        src: s,
        secs: 0,
        nanos: 0,
    }
    .parse()
}
EOF
echo ok"}

