//! Random value generators shared by the modules.

use rand::distributions::{Alphanumeric, DistString};
use rand::seq::SliceRandom;
use rand::Rng;

/// Standard normal sample via the Marsaglia polar method.
pub fn standard_normal<R: Rng>(rng: &mut R) -> f64 {
    loop {
        let u: f64 = rng.gen_range(-1.0..1.0);
        let v: f64 = rng.gen_range(-1.0..1.0);
        let s = u * u + v * v;
        if s > 0.0 && s < 1.0 {
            return u * (-2.0 * s.ln() / s).sqrt();
        }
    }
}

/// Chi-squared sample with one degree of freedom.
pub fn chi_squared_1<R: Rng>(rng: &mut R) -> f64 {
    let z = standard_normal(rng);
    z * z
}

/// Exponential sample with the given rate.
pub fn exponential<R: Rng>(rng: &mut R, rate: f64) -> f64 {
    let u: f64 = rng.gen_range(f64::EPSILON..1.0);
    -u.ln() / rate
}

/// A semver-looking version string like `0.12.5`.
pub fn gen_package_version<R: Rng>(rng: &mut R) -> String {
    let major = exponential(rng, 2.0).round() as u64;
    let minor = (chi_squared_1(rng) * 10.0).round() as u64;
    let patch = (chi_squared_1(rng) * 10.0).round() as u64;
    format!("{}.{}.{}", major, minor, patch)
}

/// Random lowercase hex string of the given length.
pub fn gen_hex_string<R: Rng>(rng: &mut R, length: usize) -> String {
    const HEX: &[u8] = b"0123456789abcdef";
    (0..length)
        .map(|_| HEX[rng.gen_range(0..HEX.len())] as char)
        .collect()
}

/// Random alphanumeric string of the given length.
pub fn gen_alphanumeric<R: Rng>(rng: &mut R, length: usize) -> String {
    Alphanumeric.sample_string(rng, length)
}

/// Random IPv4 address.
pub fn gen_ipv4<R: Rng>(rng: &mut R) -> String {
    format!(
        "{}.{}.{}.{}",
        rng.gen_range(1..255),
        rng.gen_range(0..256),
        rng.gen_range(0..256),
        rng.gen_range(1..255)
    )
}

/// Random IPv6 address with 8 groups.
pub fn gen_ipv6<R: Rng>(rng: &mut R) -> String {
    (0..8)
        .map(|_| format!("{:x}", rng.gen_range(0u32..0x10000)))
        .collect::<Vec<_>>()
        .join(":")
}

/// Random file name with one of the given extensions.
pub fn gen_file_name_with_ext<R: Rng>(rng: &mut R, names: &[&str], extensions: &[&str]) -> String {
    let name = names.choose(rng).copied().unwrap_or("file");
    let ext = extensions.choose(rng).copied().unwrap_or("bin");
    format!("{}.{}", name, ext)
}

/// Pick a random element.
pub fn pick<'a, R: Rng, T: ?Sized>(rng: &mut R, items: &'a [&'a T]) -> &'a T {
    items.choose(rng).copied().expect("non-empty list")
}

/// Pick `n` random distinct elements (fewer if the list is shorter).
pub fn pick_many<'a, R: Rng, T>(rng: &mut R, items: &'a [T], n: usize) -> Vec<&'a T> {
    items.choose_multiple(rng, n).collect()
}
