//! Static word lists used by the modules.
//!
//! Each list lives in its own text file (one entry per line) and is parsed
//! lazily on first use.

use std::sync::OnceLock;

macro_rules! word_list {
    ($name:ident, $file:expr) => {
        pub fn $name() -> &'static [&'static str] {
            static CELL: OnceLock<Vec<&'static str>> = OnceLock::new();
            CELL.get_or_init(|| {
                include_str!($file)
                    .lines()
                    .filter(|l| !l.is_empty())
                    .collect()
            })
        }
    };
}

