use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::bootlog_lines;
use crate::io::{csleep, dprint, newline};
use crate::modules::Module;

pub struct Bootlog;

impl Module for Bootlog {
    fn name(&self) -> &'static str {
        "bootlog"
    }

    fn signature(&self) -> String {
        "dmesg".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let lines = bootlog_lines();
        let num_lines = rng.gen_range(49..200);

        for _ in 0..num_lines {
            let line = *lines.choose(&mut rng).expect("bootlog data");
            let roll: f64 = rng.gen();
            let out = if roll < 0.01 {
                format!("\x1b[31mERROR: {}\x1b[0m", line)
            } else if roll < 0.11 {
                let mut words = line.split_whitespace();
                let first = words.next().unwrap_or("");
                let rest: Vec<&str> = words.collect();
                format!("\x1b[1m{}\x1b[0m {}", first, rest.join(" "))
            } else {
                line.to_string()
            };
            dprint(out, 5);
            newline();
            csleep(rng.gen_range(0..1000));
        }
    }
}
