use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::kernel_files;
use crate::generators::gen_hex_string;
use crate::io::{csleep, newline, print};
use crate::modules::Module;

pub struct KernelCompile;

pub const ARCHES: &[&str] = &[
    "alpha",
    "arc",
    "arm",
    "arm64",
    "blackfin",
    "c6x",
    "cris",
    "frv",
    "h8300",
    "hexagon",
    "ia64",
    "m32r",
    "m68k",
    "metag",
    "microblaze",
    "mips",
    "mn10300",
