    ("OBJCOPY", "arch/{ARCH}/boot/vmlinux.bin"),
    ("LDS", "arch/{ARCH}/kernel/vmlinux.lds"),
    ("PASYMS", "arch/{ARCH}/realmode/rm/pasyms.h"),
    ("EXPORTS", "lib/lib-ksyms.o"),
    ("VOFFSET", "arch/{ARCH}/boot/compressed/../voffset.h"),
    ("LDS", "arch/{ARCH}/boot/compressed/vmlinux.lds"),
    ("DATAREL", "arch/{ARCH}/boot/compressed/vmlinux"),
    ("SORTEX", "vmlinux"),
    ("LDS", "arch/{ARCH}/entry/vdso/vdso32/vdso32.lds"),
    ("RELOCS", "arch/{ARCH}/realmode/rm/realmode.relocs"),
    ("OBJCOPY", "arch/{ARCH}/boot/compressed/vmlinux.bin"),
    ("MODPOST", "vmlinux.o"),
    ("XZKERN", "arch/{ARCH}/boot/compressed/vmlinux.bin.xz"),
    ("SYSMAP", "System.map"),
];

/// Regular per-file build steps with their relative weights and the
/// extension of the produced file.
const FILE_STEPS: &[(&str, &str, u32)] = &[
    ("CC", "o", 5506),
    ("AR", "o", 2726),
    ("WRAP", "h", 305),
    ("CHK", "h", 304),
    ("UPD", "h", 304),
    ("HOSTCC", "o", 296),
    ("AS", "o", 295),
    ("SYSHDR", "h", 33),
    ("SYSTBL", "h", 31),
];

const SPECIAL_WEIGHT: u32 = 200;

/// Replace the architecture component of a kernel source path.
pub fn with_arch(path: &str, arch: &str) -> String {
    if let Some(rest) = path.strip_prefix("arch/") {
        if let Some(idx) = rest.find('/') {
            return format!("arch/{}/{}", arch, &rest[idx + 1..]);
        }
    }
    path.to_string()
}

fn strip_extension(path: &str) -> &str {
    match path.rfind('.') {
        Some(idx) if idx > path.rfind('/').map(|i| i + 1).unwrap_or(0) => &path[..idx],
        _ => path,
    }
}

impl Module for KernelCompile {
    fn name(&self) -> &'static str {
        "kernel_compile"
    }

    fn signature(&self) -> String {
        "make".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let arch = *ARCHES.choose(&mut rng).expect("arches");
        let files = kernel_files();
        let num_lines = rng.gen_range(50..500);
        let total_weight: u32 = FILE_STEPS.iter().map(|s| s.2).sum::<u32>() + SPECIAL_WEIGHT;

        for _ in 0..num_lines {
            let mut roll = rng.gen_range(0..total_weight);
            let mut line = None;
            for (tag, ext, weight) in FILE_STEPS {
                if roll < *weight {
                    let file = files.choose(&mut rng).expect("kernel data");
                    let target = format!("{}.{}", strip_extension(&with_arch(file, arch)), ext);
                    line = Some(format!("  {:<8}{}", tag, target));
                    break;
                }
                roll -= weight;
            }
            let line = line.unwrap_or_else(|| {
                let (tag, target) = SPECIAL_STEPS.choose(&mut rng).expect("special steps");
                format!("  {:<8}{}", tag, target.replace("{ARCH}", arch))
            });
            print(line);
            newline();
            csleep(rng.gen_range(0..1000));
        }

        print(format!("BUILD   arch/{}/boot/bzImage", arch));
        newline();
        csleep(rng.gen_range(0..1000));
        newline();

        let setup = rng.gen_range(9000..1_000_000u64);
        let padded = rng.gen_range(setup..1_100_000u64);
        print(format!("Setup is {} bytes (padded to {} bytes).", setup, padded));
        newline();
        print(format!("System is {} kB", rng.gen_range(300..3000)));
        newline();
        print(format!("CRC {}", gen_hex_string(&mut rng, 8)));
        newline();
        print(format!("Kernel: arch/{}/boot/bzImage is ready (#1)", arch));
        newline();
        newline();
    }
}
