        "terraform apply".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let started = Instant::now();
        let resources: &[&str] = match rng.gen_range(0..3) {
            0 => terraform_aws(),
            1 => terraform_azurerm(),
            _ => terraform_google(),
        };
        let names = terraform_names();
        let num_lines = rng.gen_range(30..300);

        print("Acquiring state lock. This may take a few moments...");
        newline();
        csleep(500);

        for _ in 1..num_lines {
            let resource = resources.choose(&mut rng).expect("terraform resources");
            let name = names.choose(&mut rng).expect("terraform names");
            let elapsed = started.elapsed().as_secs();
            let action = match rng.gen_range(0..9) {
                0 => "Creating...".to_string(),
                1 => format!("Still creating... [{}s elapsed]", elapsed),
                2 => format!("Creation complete after {}s [id={}]", elapsed, name),
                3 => format!("Modifying... [id={}]", name),
                4 => format!("Still modifying... [id={}, {}s elapsed]", name, elapsed),
                5 => format!("Modifications complete after {}s [id={}]", elapsed, name),
                6 => format!("Destroying... [id={}]", name),
                7 => format!("Destruction complete after {}s", elapsed),
                _ => format!("Refreshing state... [id={}]", name),
            };
            print(format!("\x1b[1m{}.{}: {}\x1b[0m", resource, name, action));
            newline();
            csleep(exponential(&mut rng, 1.0 / 200.0) as u64);
        }
    }
}
