        csleep(rng.gen_range(200..400));
        print("\x1b[1;32m    Updating\x1b[0m registry at `~/.julia/registries/General.toml`");
        newline();
        csleep(rng.gen_range(1000..3000));
        print("\x1b[1;32m   Resolving\x1b[0m package versions...");
        newline();
        csleep(rng.gen_range(1000..3000));

        let num_packages = rng.gen_range(10..150);
        let packages: Vec<Package> = (0..num_packages).map(|_| random_package(&mut rng)).collect();
        let width = packages.iter().map(|p| p.name.len()).max().unwrap_or(0) + 2;

        for package in &packages {
