            ));
            newline();
            print(format!(
                "\x1b[1;36m  Progress\x1b[0m {} {}/{}",
                progress_bar((i + 1) as f64 / num_artifacts as f64),
                i + 1,
                num_artifacts
            ));
            newline();
        }

        // Precompile.
        csleep(rng.gen_range(200..500));
        cursor_up(1);
        erase_line();
        print("\x1b[1;32mPrecompiling\x1b[0m project...");
        newline();
        let precompile_start = Instant::now();
