use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::{kernel_files, os_releases};
use crate::io::{csleep, newline, print};
use crate::modules::Module;

pub struct Mkinitcpio;

const REQUIRED_HOOKS: &[&str] = &["base", "udev", "autodetect", "modconf", "block", "fsck", "filesystems"];

/// All hooks in their canonical order; the optional ones are picked randomly.
const HOOK_ORDER: &[&str] = &[
    "base",
    "udev",
    "usr",
    "resume",
    "autodetect",
    "modconf",
    "block",
    "net",
    "mdadm",
    "mdadm_udev",
    "keyboard",
    "keymap",
    "consolefont",
    "encrypt",
    "lvm2",
    "fsck",
    "filesystems",
];

const COMPRESSIONS: &[&str] = &["bzip2", "gzip", "lz4", "lzma", "lzop", "xz", "zstd"];

fn msg(text: &str) {
    print(format!("\x1b[1;32m==> \x1b[0m\x1b[1m{}\x1b[0m", text));
    newline();
}

fn msg2(text: &str) {
    print(format!("\x1b[1;34m  -> \x1b[0m\x1b[1m{}\x1b[0m", text));
    newline();
}

fn warning(text: &str) {
    print(format!("\x1b[1;33m==> WARNING: \x1b[0m\x1b[1m{}\x1b[0m", text));
    newline();
}

/// Kernel module names, derived from the SCSI driver sources.
fn scsi_modules() -> Vec<&'static str> {
    kernel_files()
        .iter()
        .filter(|f| f.starts_with("drivers/scsi/"))
        .map(|f| {
            let base = f.rsplit('/').next().unwrap_or(f);
            base.strip_suffix(".c").unwrap_or(base)
        })
        .collect()
}

impl Module for Mkinitcpio {
    fn name(&self) -> &'static str {
        "mkinitcpio"
    }

    fn signature(&self) -> String {
        "mkinitcpio -p linux".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let hooks: Vec<&str> = HOOK_ORDER
            .iter()
            .copied()
            .filter(|h| REQUIRED_HOOKS.contains(h) || rng.gen_bool(0.3))
            .collect();
        let version = os_releases().choose(&mut rng).expect("os releases");
        let compression = COMPRESSIONS.choose(&mut rng).expect("compressions");
        let modules = scsi_modules();

        for preset in ["default", "fallback"] {
            let image = if preset == "default" {
                "/boot/initramfs-linux.img"
            } else {
                "/boot/initramfs-linux-fallback.img"
            };
            msg(&format!(
                "Building image from preset: /etc/mkinitcpio.d/linux.preset: '{}'",
                preset
            ));
            msg2(&format!(
                "-k /boot/vmlinuz-linux -c /etc/mkinitcpio.conf -g {}",
                image
            ));
            msg(&format!("Starting build: {}", version));

            for hook in &hooks {
                msg2(&format!("Running build hook: [{}]", hook));
                csleep(rng.gen_range(50..1000));
                if *hook == "block" && preset == "fallback" {
                    let num_warnings = rng.gen_range(0..5);
                    for _ in 0..num_warnings {
                        let module = modules.choose(&mut rng).expect("scsi modules");
                        warning(&format!("Possibly missing firmware for module: {}", module));
                    }
                    if num_warnings > 0 {
                        csleep(rng.gen_range(50..200));
                    }
                }
            }

            msg("Generating module dependencies");
            csleep(rng.gen_range(200..1000));
            msg(&format!(
                "Creating {}-compressed initcpio image: {}",
                compression, image
            ));
            csleep(rng.gen_range(1000..3000));
            msg("Image generation successful");
        }
    }
}
