];

const STATUS_CODES: &[u16] = &[200, 201, 400, 401, 403, 404, 500, 502, 503];

/// A random URL path made of a few lorem ipsum words and a file name.
pub fn gen_path<R: Rng>(rng: &mut R) -> String {
    let depth = rng.gen_range(1..5);
    let mut path = String::new();
    for _ in 0..depth {
