use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::{cargo_packages, kernel_files};
use crate::io::{csleep, newline, print};
use crate::modules::Module;

pub struct Cc;

const COMPILERS: &[&str] = &["gcc", "clang"];
const OPT_LEVELS: &[&str] = &["-O0", "-O1", "-O2", "-O3", "-Og", "-Os"];
const WARN_FLAGS: &[&str] = &[
    "-Wextra",
    "-Wwrite-strings",
    "-Wundef",
    "-Wno-unknown-pragmas",
    "-Wno-parentheses",
    "-Wno-sign-compare",
    "-Wold-style-definition",
    "-Wno-unused-variable",
];
const CODEGEN_FLAGS: &[&str] = &["-fsigned-char", "-fgnu89-inline", "-funroll-loops", "-fPIC"];
const MACHINE_FLAGS: &[&str] = &["-march=x86-64", "-mtune=generic"];
const DEFINES: &[&str] = &[
    "-DDEBUG",
    "-D_LIBS_REENTRANT",
    "-DNDEBUG",
    "-DNAMESPACE=lib",
    "-D_REENTRANT",
    "-DMODULE_NAME=lib",
    "-DSHARED",
    "-DPIC",
    "-DMATH_LOOP",
];

fn dirname(path: &str) -> &str {
    match path.rfind('/') {
        Some(idx) => &path[..idx],
        None => path,
    }
}

impl Module for Cc {
    fn name(&self) -> &'static str {
        "cc"
    }

    fn signature(&self) -> String {
        "make".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let files = kernel_files();
        let compiler = COMPILERS.choose(&mut rng).expect("compilers");

        let mut flags: Vec<&str> = vec![OPT_LEVELS.choose(&mut rng).expect("opt levels"), "-Wall"];
        for _ in 0..rng.gen_range(0..8) {
            flags.push(WARN_FLAGS.choose(&mut rng).expect("warn flags"));
        }
        for _ in 0..rng.gen_range(0..4) {
            flags.push(CODEGEN_FLAGS.choose(&mut rng).expect("codegen flags"));
        }
        for _ in 0..rng.gen_range(0..3) {
            flags.push(MACHINE_FLAGS.choose(&mut rng).expect("machine flags"));
        }
        if rng.gen_bool(0.3) {
            flags.push("-pipe");
        }
        let includes: Vec<String> = (0..20)
            .map(|_| format!("-I{}", dirname(files.choose(&mut rng).expect("kernel files"))))
            .collect();
        let defines: Vec<&str> = (0..rng.gen_range(1..8))
            .map(|_| *DEFINES.choose(&mut rng).expect("defines"))
            .collect();

        let num_files = rng.gen_range(100..1000);
        let mut chosen: Vec<&str> = files.choose_multiple(&mut rng, num_files).copied().collect();
        chosen.sort();
        let objects: Vec<String> = chosen
            .iter()
            .map(|f| format!("{}.o", f.strip_suffix(".c").unwrap_or(f)))
            .collect();

        for object in &objects {
            print(format!(
                "{} -c {} {} {} -o {}",
                compiler,
                flags.join(" "),
                includes.join(" "),
                defines.join(" "),
                object
            ));
            newline();
            csleep(rng.gen_range(0..300));
        }

        let output = cargo_packages().choose(&mut rng).expect("cargo packages");
        let libs: String = (0..rng.gen_range(0..10))
            .map(|_| format!("-l{} ", cargo_packages().choose(&mut rng).expect("cargo packages")))
            .collect();
        print(format!("{} -o {} {} {}", compiler, output, objects.join(" "), libs));
        newline();
        csleep(rng.gen_range(500..2000));
    }
}
EOF
