use crate::generators::gen_package_version;
use crate::io::{csleep, cursor_up, erase_line, newline, print};
use crate::modules::Module;

pub struct Uv;

const PYTHON_VERSIONS: &[&str] = &[
    "3.8.20", "3.9.25", "3.10.20", "3.11.15", "3.12.13", "3.13.16", "3.14.13",
];

pub const SPINNER: &[&str] = &["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];

fn format_duration(d: Duration) -> String {
    let ms = d.as_secs_f64() * 1000.0;
    if ms >= 1000.0 {
        format!("{:.2}s", ms / 1000.0)
    } else {
        format!("{:.2}ms", ms)
    }
}

fn format_size(bytes: u64) -> String {
    const MIB: f64 = 1024.0 * 1024.0;
    const KIB: f64 = 1024.0;
    let b = bytes as f64;
    if b >= MIB {
        format!("{:.2} MiB", b / MIB)
    } else {
        format!("{:.2} KiB", b / KIB)
    }
}

fn dim(text: &str) -> String {
    format!("\x1b[2m{}\x1b[0m", text)
}

impl Module for Uv {
    fn name(&self) -> &'static str {
        "uv"
    }

    fn signature(&self) -> String {
        "uv sync".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let started = Instant::now();

        print(format!(
            "Using CPython {}",
            PYTHON_VERSIONS.choose(&mut rng).expect("python versions")
        ));
        newline();
        print("Creating virtualenv at: .venv");
        newline();

        let num_resolved = rng.gen_range(128..256);
        let num_prepared = rng.gen_range(64..num_resolved);
        let packages: Vec<(&str, String)> = (0..num_resolved)
            .map(|_| {
                (
                    *cargo_packages().choose(&mut rng).expect("packages"),
                    gen_package_version(&mut rng),
                )
            })
            .collect();

        let resolve_start = Instant::now();
        for (i, (name, version)) in packages.iter().enumerate() {
            erase_line();
            print(format!("{} {}=={}", SPINNER[i % SPINNER.len()], name, version));
            csleep(rng.gen_range(50..150));
        }
        erase_line();
        print(dim(&format!(
            "Resolved {} packages in {}",
            num_resolved,
            format_duration(resolve_start.elapsed())
        )));

        let prepare_start = Instant::now();
        for i in 0..num_prepared {
            erase_line();
            print(dim(&format!(
                "{} Preparing packages... ({}/{})",
                SPINNER[i % SPINNER.len()],
                i + 1,
                num_prepared
            )));
            csleep(rng.gen_range(50..250));
        }
        erase_line();
        print(dim(&format!(
            "Prepared {} packages in {}",
            num_prepared,
            format_duration(prepare_start.elapsed())
        )));
        newline();
        newline();

        for (name, _) in &packages {
            let total: u64 = rng.gen_range(50_000..20_000_000);
            let chunk: u64 = rng.gen_range(50_000..2_000_000);
            let mut current: u64 = 0;
            loop {
                current = (current + chunk).min(total);
                let filled = ((current as f64 / total as f64) * 30.0).floor() as usize;
                let bar = format!("{}{}", "-".repeat(filled), " ".repeat(30 - filled));
                cursor_up(1);
                erase_line();
                print(format!(
                    "\x1b[2m{}\x1b[0m{}\x1b[32m{}\x1b[0m  {:>10}/{:<11}",
                    name,
                    " ".repeat(33usize.saturating_sub(name.len()).max(1)),
                    bar,
                    format_size(current),
                    format_size(total)
                ));
                newline();
                csleep(rng.gen_range(50..150));
                if current >= total {
                    break;
                }
            }
        }

        cursor_up(1);
        erase_line();
        for i in 0..=num_prepared {
            let filled = ((i as f64 / num_prepared as f64) * 30.0).ceil() as usize;
            let bar = format!(
                "{}{}",
                "\u{2588}".repeat(filled),
                "\u{2591}".repeat(30 - filled)
            );
            erase_line();
            print(format!("[{}] [{}/{}] Installing wheels...", bar, i, num_prepared));
            csleep(rng.gen_range(50..150));
        }
        erase_line();
        print(dim(&format!(
            "Installed {} packages in {}",
            num_prepared,
            format_duration(started.elapsed())
        )));
        newline();
    }
}
