use rand::Rng;

use crate::args::AppConfig;
use crate::io::{csleep, cursor_up, dprint, erase_line, newline, print};
use crate::modules::Module;

pub struct Botnet;

const BOOTING: &str = "\x1b[1;33mbooting\x1b[0m";
const ONLINE: &str = "\x1b[1;32monline\x1b[0m";

impl Module for Botnet {
    fn name(&self) -> &'static str {
        "botnet"
    }

    fn signature(&self) -> String {
        "./botnet.sh --connect-all".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let num_clusters = rng.gen_range(8..17);
        let clusters: Vec<u32> = (0..num_clusters).map(|_| rng.gen_range(100..=200)).collect();
        let total: u32 = clusters.iter().sum();

        for i in 0..=total {
            print(format!("\rEstablishing connections: {:>4}/{}", i, total));
            csleep(rng.gen_range(0..15));
        }
        newline();

        for (i, nodes) in clusters.iter().enumerate() {
            dprint(format!("  Cluster #{:02} ({} nodes)", i, nodes), 10);
            newline();
            csleep(100);
        }

        let mut online = vec![false; num_clusters];
        loop {
            csleep(rng.gen_range(50..400));
            cursor_up(num_clusters as u64);
            for (i, nodes) in clusters.iter().enumerate() {
                erase_line();
                print(format!(
                    "  Cluster #{:02} ({} nodes) [{}]",
                    i,
                    nodes,
                    if online[i] { ONLINE } else { BOOTING }
                ));
                newline();
            }
            if online.iter().all(|&o| o) {
