use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::first_names;
use crate::generators::gen_hex_string;
use crate::io::{csleep, cursor_up, newline, print};
use crate::modules::Module;

pub struct Bruteforce;

/// 256-color rainbow used for the rainbow table progress bar.
const RAINBOW: [u8; 30] = [
    203, 209, 208, 178, 178, 184, 148, 154, 119, 119, 83, 84, 48, 43, 44, 44, 38, 33, 69, 63, 99,
    99, 129, 128, 164, 163, 163, 198, 204, 203,
];

const SPINNER: [char; 4] = ['|', '/', '-', '\\'];

impl Module for Bruteforce {
    fn name(&self) -> &'static str {
        "bruteforce"
    }

    fn signature(&self) -> String {
        "./decrypt.sh --hash-file hashes.txt".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let num_hashes = rng.gen_range(2..10);
        let hashes: Vec<String> = (0..num_hashes).map(|_| gen_hex_string(&mut rng, 64)).collect();

        print("=> Hashes to decrypt");
        newline();
        csleep(500);
        for hash in &hashes {
            print(format!("  {}", hash));
            newline();
        }
        newline();
        csleep(500);

        for step in 0..=RAINBOW.len() {
            let mut bar = String::new();
            for (i, color) in RAINBOW.iter().enumerate() {
                let c = if i < step {
                    '='
                } else if i == step {
                    SPINNER[step % SPINNER.len()]
                } else {
                    ' '
                };
                bar.push_str(&format!("\x1b[38;5;{}m{}\x1b[0m", color, c));
            }
            print(format!("\r=> Extracting Rainbow Table [{}]", bar));
            csleep(rng.gen_range(50..200));
        }
        newline();
        csleep(200);
        print("=> Begin matching");
        newline();
        csleep(500);

        let mut matched = vec![0usize; num_hashes];
        let mut first = true;
        loop {
            if !first {
                cursor_up(num_hashes as u64);
            }
            first = false;
            for (hash, m) in hashes.iter().zip(matched.iter()) {
                print(format!(
                    "\r :: \x1b[32m{}\x1b[0m\x1b[31m{}\x1b[0m ::",
                    &hash[..*m],
                    gen_hex_string(&mut rng, 64 - *m)
                ));
                newline();
            }
            if matched.iter().all(|&m| m >= 64) {
                break;
            }
            csleep(30);
            for m in matched.iter_mut() {
                while *m < 64 && rng.gen_ratio(1, 16) {
                    *m += 1;
                }
            }
        }

        print("=> Match found");
        newline();
        for hash in &hashes {
            let name = first_names().choose(&mut rng).expect("first names");
            print(format!(
                "  {}:\x1b[1m{}{:02}\x1b[0m",
                hash,
                name,
                rng.gen_range(0..100)
            ));
            newline();
        }
    }
}
