use std::time::Instant;

use rand::Rng;

use crate::args::AppConfig;
use crate::generators::{gen_hex_string, standard_normal};
use crate::io::{csleep, newline, print};
use crate::modules::Module;

pub struct Cryptomining;

fn info_prefix(source: &str) -> String {
    format!(
        "\x1b[1;36m  \u{2139}\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34m{:<13}\x1b[0m",
        chrono::Utc::now().format("%H:%M:%S"),
        source
    )
}

impl Module for Cryptomining {
    fn name(&self) -> &'static str {
        "cryptomining"
    }

    fn signature(&self) -> String {
        "./cryptominer.sh --gpu all --provider stratum".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let started = Instant::now();
        let num_gpus = rng.gen_range(1..8);
        let base_speed: f64 = rng.gen_range(1.0..100.0);
        let job_interval = rng.gen_range(20..50);
        let solution_interval = rng.gen_range(80..200);
        let num_lines = rng.gen_range(300..1000);

        let mut printed = 0;
        let mut iteration = 0u64;
        let mut accepted = 0u64;
        while printed < num_lines {
            let gpus: Vec<f64> = (0..num_gpus)
                .map(|_| base_speed + standard_normal(&mut rng) * 0.2)
                .collect();
            let total: f64 = gpus.iter().sum();
            let gpu_text: String = gpus
                .iter()
                .enumerate()
                .map(|(i, g)| format!("gpu/{} \x1b[36m{:.2}\x1b[0m ", i, g))
                .collect();
            let elapsed = started.elapsed().as_secs();
            print(format!(
                "\x1b[32m  m\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mcryptominer  \x1b[0mSpeed \x1b[1;36m{:>6.2}\x1b[0m Mh/s    {}  [A{}+0:R0+0:F0] Time: {:02}:{:02}",
                chrono::Utc::now().format("%H:%M:%S"),
                total,
                gpu_text,
                accepted,
                elapsed / 3600,
                (elapsed / 60) % 60
            ));
            newline();
            printed += 1;
            iteration += 1;

            if iteration % job_interval == 0 {
                print(format!(
                    "{}Received new job #{}  seed: #{}  target: #{}",
                    info_prefix("stratum"),
                    gen_hex_string(&mut rng, 8),
                    gen_hex_string(&mut rng, 32),
                    gen_hex_string(&mut rng, 24)
                ));
                newline();
                printed += 1;
            }
            if iteration % solution_interval == 0 {
                print(format!(
                    "{}Solution found; Submitted to stratum.buttcoin.org",
                    info_prefix("CUDA0")
                ));
                newline();
                print(format!(
                    "{}Nonce: 0x{}",
                    info_prefix("CUDA0"),
                    gen_hex_string(&mut rng, 16)
                ));
                newline();
                print(format!("{}\x1b[32mAccepted.\x1b[0m", info_prefix("stratum")));
                newline();
                accepted += 1;
                printed += 3;
            }
            csleep(rng.gen_range(0..600));
        }
    }
}
