use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::simcity_messages;
use crate::io::{csleep, dprint, newline, print, should_exit};
use crate::modules::Module;

pub struct Simcity;

const SPINNER: [char; 4] = ['/', '-', '\\', '|'];

/// Picks a completion status and colour; FAIL is always red.
fn pick_status<R: Rng>(rng: &mut R) -> (&'static str, u8) {
    let roll: f64 = rng.gen();
    let status = if roll < 0.82 {
        "OK"
    } else if roll < 0.90 {
        "SUCCESS"
    } else if roll < 0.95 {
        "FAIL"
    } else {
        "YES"
    };
    let color = if status == "FAIL" {
        31
    } else if rng.gen_bool(0.75) {
        37
    } else {
        *[31u8, 32, 34, 36].choose(rng).unwrap()
    };
    (status, color)
}

impl Module for Simcity {
    fn name(&self) -> &'static str {
        "simcity"
    }

    fn signature(&self) -> String {
        "simcity".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let messages = simcity_messages();

        for _ in 0..500 {
            let message = *messages.choose(&mut rng).expect("simcity data");
            // Type out the task line, ending with the first spinner frame.
            for c in format!("[ ] {}... ", message).chars() {
                print(c.to_string());
                csleep(rng.gen_range(10..120));
            }
            print(SPINNER[0].to_string());

            let cycles = rng.gen_range(1..20);
            let mut aborted = false;
            'spin: for _ in 0..cycles {
                for frame in 1..=SPINNER.len() {
                    csleep(50);
                    let spinner = SPINNER[frame % SPINNER.len()];
                    for c in format!("\r[ ] {}... {}", message, spinner).chars() {
                        print(c.to_string());
                    }
                }
                if should_exit() {
                    aborted = true;
                    break 'spin;
                }
            }

            if aborted {
                let status = if rng.gen_bool(0.96) {
                    "ABORTED"
                } else {
                    pick_status(&mut rng).0
                };
                println!("\r[o] \x1b[31m{}... {}\x1b[0m", message, status);
                println!("ALL DONE");
                return;
            }

            let (status, color) = pick_status(&mut rng);
            print(format!("\r[o] \x1b[{}m{}... {}\x1b[0m", color, message, status));
            newline();
        }
    }
}
