import re
rows=[]
for l in open('/tmp/timing/wpt.txt'):
    m=re.match(r'\s*([\d.]+)ms\s\s(.*)',l)
    if m: rows.append((float(m.group(1)), m.group(2)))
# classify chunks: S=status, E=event-ish
kinds=[]
for t,s in rows:
    if re.search(r'\\e\[A\\e\[K\[\d+/', s): kinds.append(('S',t))
    elif '▶' in s or '│' in s or '└' in s or s.strip()=='\\r\\n': kinds.append(('E',t))
    else: kinds.append(('O',t))
# collapse consecutive E into one group
groups=[]
for k,t in kinds:
