use rand::Rng;

use crate::args::AppConfig;
use crate::data::wpt_dirs;
use crate::io::{csleep, newline, print, should_exit};
use crate::modules::Module;

pub struct Wpt;

const ENCODINGS: &[&str] = &["big5-decode", "eucjp-decode", "eucjp-encode-form", "shift-jis-decode"];
const PATH_FUNCS: &[&str] = &["test", "testGetBoundingClientRect", "check", "assert", "verify"];
