/// Cumulative distribution of the number of failures reported per test.
const EVENT_COUNT_CDF: &[f64] = &[0.442, 0.751, 0.902, 0.968, 0.992, 0.998, 1.0];

struct Test {
    path: String,
    name: String,
}

fn gen_test<R: Rng>(rng: &mut R) -> Test {
    let dir = *wpt_dirs().choose(rng).expect("wpt dirs");
    if dir.contains("legacy-mb") && rng.gen_bool(0.75) {
        let lang = dir.rsplit('/').next().unwrap_or(dir);
        let encoding = ENCODINGS.choose(rng).unwrap();
        let name = format!("{}-{}", encoding, lang);
        let block = rng.gen_range(1..20);
        Test {
            path: format!("{}/{}.html?{}000-{}999", dir, name, block, block),
            name,
        }
    } else {
        let number = rng.gen_range(1..500);
        Test {
            path: format!("{}/test-{}.html", dir, number),
            name: format!("test-{}", number),
        }
    }
}

fn gen_assertion<R: Rng>(rng: &mut R) -> String {
    match rng.gen_range(0..5) {
        0 => format!(
            "assert_equals: expected {} but got {}",
            rng.gen_range(0..1000),
            rng.gen_range(0..1000)
        ),
        1 => "assert_throws_dom: function \"() => test()\" threw object \"TypeError: undefined is not a function\" that is not a DOMException".to_string(),
        2 => format!(
            "assert_array_equals: expected property {} to be {} but got {}",
            rng.gen_range(1..10),
            rng.gen_range(0..1000),
            rng.gen_range(0..1000)
        ),
        3 => format!(
            "assert_approx_equals: expected {} +/- {} but got {}",
            rng.gen_range(0..1000),
            rng.gen_range(1..10),
            rng.gen_range(0..1000)
        ),
        _ => "assert_true: expected true but got false".to_string(),
    }
}

fn gen_frame<R: Rng>(rng: &mut R, test_path: &str) -> String {
    let roll: f64 = rng.gen();
    let line = rng.gen_range(1..150);
    let col = rng.gen_range(1..100);
    let harness_line = HARNESS_LINES.choose(rng).unwrap();
    if roll < 0.23 {
        "<unknown>".to_string()
    } else if roll < 0.504 {
        format!("http://web-platform.test:8000/{}:{}:{}", test_path, line, col)
    } else if roll < 0.572 {
        format!(
            "{} (http://web-platform.test:8000/{}:{}:{})",
            PATH_FUNCS.choose(rng).unwrap(),
            test_path,
            line,
            col
        )
    } else if roll < 0.684 {
        format!(
            "http://web-platform.test:8000/resources/testharness.js:{}:{}",
            harness_line,
            rng.gen_range(20..50)
        )
    } else if roll < 0.851 {
        format!(
            "assert_wrapper (http://web-platform.test:8000/resources/testharness.js:{}:35)",
            harness_line
        )
    } else {
        format!(
            "test (http://web-platform.test:8000/resources/testharness.js:{}:34)",
            harness_line
        )
    }
}

fn print_event<R: Rng>(rng: &mut R, test: Option<&Test>) {
    let (path, name) = match test {
        Some(t) => (t.path.as_str(), t.name.as_str()),
        None => ("", ""),
    };
    let expected_fail = rng.gen_bool(0.5);
    let expected = if expected_fail { "FAIL" } else { "PASS" };
    let assertion = if expected_fail {
        "assert_".to_string()
    } else {
        gen_assertion(rng)
    };
    if rng.gen_bool(0.5) {
        print(format!("\x1b[A\x1b[K    \u{25b6} Timed out in {}", path));
        newline();
        print(format!(
            "    \u{2502} ERROR [expected {}] TIMEOUT test_{} {}",
            expected, name, assertion
        ));
        newline();
    } else {
        let result = if expected_fail { "PASS" } else { "FAIL" };
        print(format!(
            "\x1b[A\x1b[K    \u{25b6} Unexpected subtest result in {}:",
            path
        ));
        newline();
        print(format!(
            "    \u{2502} ERROR [expected {}] {} test_{} {}",
            expected, result, name, assertion
        ));
        newline();
        let depth = rng.gen_range(3..9);
        for i in 0..depth {
            let glyph = if i + 1 == depth { '\u{2514}' } else { '\u{2502}' };
            print(format!("    {}   at {}", glyph, gen_frame(rng, path)));
            newline();
        }
        newline();
    }
}

fn gen_event_count<R: Rng>(rng: &mut R) -> usize {
    let roll: f64 = rng.gen();
    EVENT_COUNT_CDF.iter().position(|&p| roll < p).unwrap_or(EVENT_COUNT_CDF.len() - 1)
}

impl Module for Wpt {
    fn name(&self) -> &'static str {
        "wpt"
    }

    fn signature(&self) -> String {
        "wpt run".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let total: u64 = rng.gen_range(5000..30000);
        let mut done: u64 = 0;
        let mut failed: u64 = 0;
        let mut subtests: u64 = 0;
        let mut current: Option<Test> = None;
        let mut previous_empty = true;

        print(format!("Running {} tests in web-platform-tests", total));
        newline();
        csleep(rng.gen_range(1000..3000));

        let mut running: Vec<Test> = Vec::new();
        loop {
            running = (0..rng.gen_range(0..16)).map(|_| gen_test(&mut rng)).collect();

            if previous_empty {
                print(format!("\x1b[A\x1b[K[{}/{}] No tests running.", done, total));
                newline();
            } else {
                let list: String = running.iter().map(|t| format!("{} ", t.path)).collect();
                print(format!("\x1b[A\x1b[K[{}/{}] {}", done, total, list));
                newline();
                if let Some(last) = running.last() {
                    current = Some(Test {
                        path: last.path.clone(),
                        name: last.name.clone(),
                    });
                }
            }

            for _ in &running {
                csleep(rng.gen_range(0..100));
                subtests += rng.gen_range(0..64);
                for _ in 0..gen_event_count(&mut rng) {
                    print_event(&mut rng, current.as_ref());
                    failed += 1;
                }
            }

            done += running.len() as u64;
            previous_empty = running.is_empty();

            if done >= total || should_exit() {
                break;
            }
        }

        print(format!(
            "\x1b[A\x1b[KRan {}/{} tests with {} failed subtests of {}.",
            done + running.len() as u64,
            total,
            failed,
            subtests
        ));
        newline();
    }
}
