use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::kernel_files;
use crate::io::{csleep, erase_line, get_terminal_width, newline, print, should_exit};
use crate::modules::Module;
use crate::modules::weblog::FILE_EXTENSIONS;

pub struct Download;

fn format_size(bytes: f64) -> String {
    const MIB: f64 = 1024.0 * 1024.0;
    const KIB: f64 = 1024.0;
    if bytes >= MIB {
        format!("{:.2}MiB", bytes / MIB)
    } else {
        format!("{:.2}KiB", bytes / KIB)
    }
}

fn bar(fraction: f64, width: usize, complete: bool) -> String {
    if complete {
        return "=".repeat(width);
    }
    if fraction <= 0.0 {
        return " ".repeat(width);
    }
    let filled = ((fraction * width as f64).floor() as usize).min(width.saturating_sub(1));
    format!(
        "{}\u{2588}{}",
        "=".repeat(filled),
        " ".repeat(width.saturating_sub(filled + 1))
    )
}

impl Module for Download {
    fn name(&self) -> &'static str {
        "download"
    }

    fn signature(&self) -> String {
        "wget -i downloads.txt".to_string()
    }

    fn run(&self, _config: &AppConfig) {
        let mut rng = rand::thread_rng();
        let width = get_terminal_width();
        let name_width = ((width as f64 / 3.0).round() as usize).saturating_sub(9);
        let bar_width = width.saturating_sub(46 + name_width).max(1);
        let extension = FILE_EXTENSIONS.choose(&mut rng).expect("extensions");
        let num_files = rng.gen_range(3..10);

        for _ in 0..num_files {
            let file = kernel_files().choose(&mut rng).expect("kernel files");
            let stem = file.rsplit('/').next().unwrap_or(file);
            let stem = stem.strip_suffix(".c").unwrap_or(stem);
            let name = format!("{}.{}", stem, extension);
            let total: f64 = rng.gen_range(30_000_000.0..300_000_000.0);
            let mut downloaded = 0.0f64;
            let mut first = true;

            loop {
                let chunk: f64 = rng.gen_range(750_000.0..1_250_000.0);
                let speed = chunk * 20.0;
                let fraction = downloaded / total;
                let eta = if first {
                    0
                } else {
                    ((total - downloaded) / speed).max(0.0) as u64
                };
                let percent = (fraction * 100.0).round() as u64;
                let complete = downloaded >= total;
                erase_line();
                print(format!(
                    "{:<nw$}{:>3}%[{}] {:<11}{}/s   eta {}s",
                    name,
                    percent.min(100),
                    bar(fraction, bar_width, complete),
                    format_size(chunk),
                    format_size(speed),
                    eta,
                    nw = name_width
                ));
                if complete {
                    break;
                }
                downloaded = (downloaded + chunk).min(total);
                first = false;
                csleep(50);
                if should_exit() {
                    return;
                }
            }
            newline();
        }
    }
}
