use rand::seq::SliceRandom;
use rand::Rng;

use crate::args::AppConfig;
use crate::data::{ansible_roles, ansible_tasks, first_names, lorem_words};
use crate::generators::{gen_ipv4, gen_ipv6};
use crate::io::{csleep, get_terminal_width, newline, print, should_exit};
use crate::modules::Module;

pub struct Ansible;

/// Pads a header line with asterisks up to the terminal width.
fn header(text: &str, width: usize) -> String {
    let stars = width.saturating_sub(text.len() + 1);
    format!("{} {}", text, "*".repeat(stars))
}

fn result<R: Rng>(rng: &mut R, host: &str) -> String {
    let roll: f64 = rng.gen();
    let (color, status) = if roll < 0.76 {
        (32, "ok")
    } else if roll < 0.865 {
        (33, "changed")
    } else if roll < 0.932 {
        (31, "failed")
    } else {
        (36, "skipping")
    };
    format!("\x1b[{}m{}: [{}]\x1b[0m", color, status, host)
