/// Pads a header line with asterisks up to the terminal width.
fn header(text: &str, width: usize) -> String {
    let stars = width.saturating_sub(text.len() + 1);
    format!("{} {}", text, "*".repeat(stars))
}

fn result<R: Rng>(rng: &mut R, host: &str) -> String {
    let roll: f64 = rng.gen();
    let (color, status) = if roll < 0.76 {
