//! Best-effort idle inhibition via the system D-Bus socket.
//!
//! Without a reachable system bus (the common case in containers) this only
//! reports a warning, mirroring the reference behaviour.

use std::os::unix::net::UnixStream;

fn system_bus_path() -> String {
    if let Ok(addr) = std::env::var("DBUS_SYSTEM_BUS_ADDRESS") {
        for part in addr.split(';') {
            if let Some(rest) = part.strip_prefix("unix:") {
                for kv in rest.split(',') {
                    if let Some(path) = kv.strip_prefix("path=") {
                        return path.to_string();
                    }
                }
            }
        }
    }
    "/var/run/dbus/system_bus_socket".to_string()
}

/// Tries to connect to the system bus; the returned stream keeps the
/// connection alive for the lifetime of the program.
pub fn setup() -> Option<UnixStream> {
    match UnixStream::connect(system_bus_path()) {
        Ok(stream) => Some(stream),
        Err(err) => {
            eprintln!(
                "WARN: failed to set up idle inhibition: system: I/O error: {}",
                err
            );
            None
        }
    }
}
