//! Output helpers: speed-adjusted sleeping, delayed printing, cursor control.
//!
//! All modules write through [`print`] so that the global speed factor,
//! the `--instant-print-lines` option and the `--exit-after-time` deadline
//! are handled in one place.

use std::io::{self, Write};
use std::sync::atomic::{AtomicBool, AtomicU32, AtomicU64, Ordering};
use std::sync::OnceLock;
use std::time::{Duration, Instant};

static SPEED_FACTOR_BITS: AtomicU32 = AtomicU32::new(0x3f80_0000); // 1.0f32
static INSTANT_PRINT_LINES: AtomicU32 = AtomicU32::new(0);
static SKIPPED_SLEEPS: AtomicU64 = AtomicU64::new(0);
/// Reference point for `--exit-after-time`; initialised lazily on the first check.
static START: OnceLock<Instant> = OnceLock::new();
static EXIT_AFTER: OnceLock<Duration> = OnceLock::new();
static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);

pub fn setup(speed_factor: f32, instant_print_lines: u32, exit_after: Option<Duration>) {
    SPEED_FACTOR_BITS.store(speed_factor.to_bits(), Ordering::SeqCst);
    INSTANT_PRINT_LINES.store(instant_print_lines, Ordering::SeqCst);
    if let Some(d) = exit_after {
        let _ = EXIT_AFTER.set(d);
    }
}

pub fn speed_factor() -> f32 {
    f32::from_bits(SPEED_FACTOR_BITS.load(Ordering::Relaxed))
}

/// Prints the farewell message and terminates the process.
pub fn exit_handler() -> ! {
    let _ = io::stdout().flush();
    println!("Saving work to disk...");
    let _ = io::stdout().flush();
    std::process::exit(0);
}

/// Whether the modules should wrap up because the run time limit has been
/// reached. Modules poll this at convenient points in their loops.
pub fn should_exit() -> bool {
    if SHOULD_EXIT.load(Ordering::Relaxed) {
        return true;
    }
    match EXIT_AFTER.get() {
        Some(limit) => {
            let start = START.get_or_init(Instant::now);
            start.elapsed() >= *limit
        }
        None => false,
    }
}

/// The first `--instant-print-lines` sleeps are skipped so that output
/// appears immediately.
fn skip_for_instant_print() -> bool {
    let limit = INSTANT_PRINT_LINES.load(Ordering::Relaxed) as u64;
    if SKIPPED_SLEEPS.load(Ordering::Relaxed) < limit {
        SKIPPED_SLEEPS.fetch_add(1, Ordering::Relaxed);
        return true;
    }
    false
}

/// Sleep for `ms` milliseconds, adjusted by the global speed factor.
pub fn csleep(ms: u64) {
    if skip_for_instant_print() {
        return;
    }
    let sf = speed_factor() as f64;
    let adjusted = (ms as f64) / sf;
    if adjusted > 0.0 {
        std::thread::sleep(Duration::from_secs_f64(adjusted / 1000.0));
    }
}

/// Print a string without a trailing newline and flush.
///
/// Writing goes through the standard output handle; when the output has been
/// closed (for example a broken pipe) the resulting error is fatal, like it
/// would be for `println!`.
pub fn print<S: AsRef<str>>(s: S) {
    print!("{}", s.as_ref());
    io::stdout().flush().unwrap();
}

/// Print a line terminator (`\r\n`).
pub fn newline() {
    print("\r\n");
}

/// Print a string character by character with a delay between characters.
pub fn dprint<S: AsRef<str>>(s: S, delay_ms: u64) {
    for c in s.as_ref().chars() {
        print(c.to_string());
        if delay_ms > 0 {
            csleep(delay_ms);
        }
    }
}

pub fn cursor_up(n: u64) {
    print(format!("\x1b[{}A", n));
}

pub fn erase_line() {
    print("\x1b[2K\x1b[0G");
}

/// Returns the terminal width, panicking if there's no terminal attached.
pub fn get_terminal_width() -> usize {
    terminal_size().map(|(w, _)| w).unwrap_or_else(|| {
        panic!("Couldn't get terminal width. Is an interactive terminal attached?")
    })
}

/// Returns the size (columns, rows) of the terminal attached to stdout,
/// stderr or stdin (checked in that order).
pub fn terminal_size() -> Option<(usize, usize)> {
    let fds = [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO];
    for fd in fds {
        if unsafe { libc::isatty(fd) } != 1 {
            continue;
        }
        let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
        let r = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) };
        if r == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
            return Some((ws.ws_col as usize, ws.ws_row as usize));
        }
    }
    None
}
